layer.css:
[data-ryt="footer"] { color: rgb(100, 116, 139); background-color: rgb(15, 23, 42); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { background-color: var(--ryt-surface); border-top: 1px solid color-mix(in srgb, var(--ryt-border) 18%, transparent); border-right: 1px solid color-mix(in srgb, var(--ryt-border) 18%, transparent); border-bottom: 1px solid color-mix(in srgb, var(--ryt-border) 18%, transparent); border-left: 1px solid color-mix(in srgb, var(--ryt-border) 18%, transparent); border-radius: 6px; transition: 0.3s ease-out }
[data-ryt="brand"] { color: #878f97; border-radius: 0px; font-family: Mulish; font-size: 20px; font-weight: 600; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(203, 213, 225); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.3s ease-out }
[data-ryt="nav"] a { color: #188ba8; background-color: rgba(8, 145, 178, 0.094); border-bottom: 2px solid rgba(8, 145, 178, 0.925); border-radius: 0px; font-family: Mulish; font-size: 16px; font-weight: 500; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 8px; padding-bottom: 8px; padding-left: 8px; transition: 0.3s ease-out; border-top: none; border-right: none; border-left: none }
[data-ryt="button"] { color: rgb(228, 228, 231); background-color: rgb(51, 65, 85); border-top: 1px solid rgb(51, 65, 85); border-right: 1px solid rgb(51, 65, 85); border-bottom: 1px solid rgb(51, 65, 85); border-left: 1px solid rgb(51, 65, 85); border-radius: 6px; font-family: Mulish; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(228, 228, 231); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 6px; padding-right: 12px; padding-bottom: 6px; padding-left: 12px; transition: 0.3s ease-out }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: rgb(8, 145, 178); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(8, 145, 178); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.3s ease-out }
[data-ryt="review"] { color: rgb(51, 65, 85); font-family: Mulish; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(51, 65, 85); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: Mulish; font-size: 18px; font-weight: 500; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: rgb(6, 182, 212) }
[data-ryt="button"]:hover { color: #fff; background-color: #424649; background-color: rgb(8, 145, 178); border-top-color: rgb(8, 145, 178); border-right-color: rgb(8, 145, 178); border-bottom-color: rgb(8, 145, 178); border-left-color: rgb(8, 145, 178) }
[data-ryt="nav"] a:hover { color: color-mix(in srgb, var(--ryt-border) 80%, transparent); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: rgb(6, 182, 212); background-image: initial; background-color: rgba(8, 145, 178, 0.1); color: rgb(8, 145, 178); border-bottom-width: 2px; border-bottom-style: solid; border-bottom-color: rgb(8, 145, 178) }
[data-ryt="brand"]:hover { color: var(--ryt-border); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: rgb(6, 182, 212) }
article[data-ryt="rec-card"]:hover { box-shadow: rgba(15, 80, 100, 0.16) 0px 8px 56px; border-top-width: 1px; border-right-width: 1px; border-bottom-width: 1px; border-left-width: 1px; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-color: var(--ryt-bg); border-right-color: var(--ryt-bg); border-bottom-color: var(--ryt-bg); border-left-color: var(--ryt-bg) }
